# Toy CPU: which guest instructions does the VMM get to see?
PRIVILEGED = {"HLT", "OUT", "MOV_CR3"}       # fault outside ring 0
SENSITIVE  = {"HLT", "OUT", "MOV_CR3", "SGDT"}  # touch machine state

def run_guest(program):
    for insn in program:
        if insn in PRIVILEGED:            # guest kernel runs deprivileged,
            print(f"{insn:8} trap  : VMM emulates it")   # so these fault
        elif insn in SENSITIVE:
            print(f"{insn:8} runs  : guest sees REAL host state")
        else:
            print(f"{insn:8} runs  natively (harmless)")

run_guest(["ADD", "OUT", "SGDT", "MOV_CR3", "HLT"])

# Toy two-dimensional walk: 16-bit addresses, 4 KiB pages, 2-level tables.
# Each table index is 2 bits here (real x86-64: 9 bits per level, 4 levels).
R, W, X = 1, 2, 4
host_mem = {}                       # host physical address: table entry
refs = []                           # every memory read the "hardware" makes

def read(hpa, why):
    refs.append(why)
    return host_mem.get(hpa)

def ept_walk(gpa, need, eptp=0x1000):
    """guest-physical to host-physical, checking R/W/X like EPT does"""
    table = eptp
    for level, shift in ((2, 14), (1, 12)):
        idx = (gpa >> shift) & 0x3
        entry = read(table + idx * 8, f"EPT L{level} for gPA {gpa:#06x}")
        if entry is None or not (entry[1] & need) == need:
            raise PermissionError(f"EPT violation (exit 48) at gPA {gpa:#06x}")
        table = entry[0]
    return table | (gpa & 0xFFF)

def guest_walk(gva, guest_cr3):
    table_gpa = guest_cr3
    for level, shift in ((2, 14), (1, 12)):
        idx = (gva >> shift) & 0x3
        entry_hpa = ept_walk(table_gpa + idx * 8, R)   # each guest table read

# Device-side checks on a descriptor the guest wrote into shared memory.
QUEUE_SIZE, MAX_LEN, GUEST_RAM = 256, 64 * 1024, 0x4000_0000

def check_chain(descs, head):
    seen, i, total = 0, head, 0
    while True:
        if not 0 <= i < QUEUE_SIZE:
            return f"reject: index {i} outside the queue"
        addr, length, nxt = descs[i]
        if length > MAX_LEN:
            return f"reject: length {length} too large"
        if addr + length > GUEST_RAM or addr + length < addr:
            return "reject: buffer runs outside guest RAM"
        total += length
        seen += 1
        if seen > QUEUE_SIZE:                 # the spec forbids loops for
            return "reject: chain loops"      # drivers; devices must check
        if nxt is None:
            return f"ok: {seen} buffers, {total} bytes"
        i = nxt

descs = {0: (0x1000, 512, 1), 1: (0x2000, 512, None),
         2: (0x3000, 64, 3), 3: (0x4000, 64, 2),            # 2 and 3 loop
         4: (0x3FFF_FF00, 4096, None), 5: (0x5000, 8, 999)}
for head in (0, 2, 4, 5):
    print(f"head {head}: {check_chain(descs, head)}")

# ToyFIFO: a made-up emulated device. The guest writes bytes to one data port.
# Byte 0 is a command, then its parameters. Device state is one flat buffer,
# like a C struct: a 16-byte FIFO followed by the DMA base address.
FIFO_LEN, DMA_OFF = 16, 16
PARAMS = {0x01: 2, 0x02: 0, 0x05: 1}          # ECHO, STATUS, READ_ID

class ToyFifoVulnerable:
    def __init__(self):
        self.mem = bytearray(20)              # fifo[16] + dma_base[4]
        self.mem[DMA_OFF:] = (0x8000).to_bytes(4, "little")
        self.pos, self.length = 0, 0
    def dma_base(self):
        return int.from_bytes(self.mem[DMA_OFF:], "little")
    def write_data(self, value):
        if self.pos == 0:                     # first byte: a command
            self.length = PARAMS.get(value, 0) + 1
        self.mem[self.pos] = value            # BUG: pos never checked
        self.pos += 1
        if self.pos == self.length:
            self.run_command(self.mem[0])
    def run_command(self, cmd):
        if cmd == 0x05:
            pass                              # READ_ID: finishes on a timer;
        else:                                 # pos is reset only then
            self.pos = 0

import random
from toydev import ToyFifoVulnerable, ToyFifoFixed

def fuzz(cls, runs=2000, seed=1):
    rng = random.Random(seed)
    for i in range(runs):
        dev = cls()
        data = [rng.choice([0x01, 0x02, 0x05, rng.randrange(256)])
                for _ in range(rng.randrange(1, 40))]
        try:
            for b in data:
                dev.write_data(b)
        except IndexError:
            return f"run {i}: crashed (wrote past the end of device memory)"
        if dev.dma_base() != 0x8000:          # invariant: guest bytes must
            return f"run {i}: dma_base corrupted to {dev.dma_base():#x}"
    return f"{runs} runs, invariant held"

for cls in (ToyFifoVulnerable, ToyFifoFixed):
    print(f"{cls.__name__:18} {fuzz(cls)}")

