# A synthetic listing of /sys/devices/system/cpu/vulnerabilities/ from a KVM
# host, using the exact string formats in the kernel's arch/x86 bugs.c.
LISTING = {
    "l1tf":       "Mitigation: PTE Inversion; VMX: conditional cache flushes, SMT vulnerable",
    "mds":        "Mitigation: Clear CPU buffers; SMT vulnerable",
    "spectre_v2": "Mitigation: Enhanced / Automatic IBRS; IBPB: conditional; RSB filling; PBRSB-eIBRS: SW sequence; BHI: BHI_DIS_S",
    "meltdown":   "Not affected",
}
VM_RELEVANT = ["l1tf", "mds", "spectre_v2", "vmscape"]
SMT_ACTIVE = True                      # from /sys/devices/system/cpu/smt/active

def review(listing, untrusted_guests=True):
    for issue in VM_RELEVANT:
        state = listing.get(issue)
        if state is None:
            print(f"UNKNOWN {issue}: no file, kernel predates this check: update it")
        elif state.startswith("Vulnerable"):
            print(f"ACTION  {issue}: {state}")
        elif "SMT vulnerable" in state and untrusted_guests:
            print(f"REVIEW  {issue}: guest and host can share a core via SMT")
        else:
            print(f"ok      {issue}: {state.split(';')[0]}")
    if SMT_ACTIVE and untrusted_guests:
        print("REVIEW  SMT active with untrusted guests: nosmt or core scheduling")

review(LISTING)

import hashlib, struct
from snp_make import make_report, tcb

EXPECTED = hashlib.sha384(b"ovmf+kernel+initrd+cmdline v42").digest()
MIN_TCB = {"boot": 3, "tee": 0, "snp": 8, "ucode": 115}

def verify(report, nonce):
    # Step 0 (not shown): check the ECDSA P-384 signature over bytes
    # 0x0-0x29F with the chip's VCEK, chained to AMD's root key.
    problems = []
    version, svn, policy = struct.unpack_from("<IIQ", report, 0x00)
    platform = struct.unpack_from("<Q", report, 0x40)[0]
    t = struct.unpack_from("<Q", report, 0x180)[0]
    got = {"boot": t & 0xFF, "tee": t >> 8 & 0xFF, "snp": t >> 48 & 0xFF, "ucode": t >> 56}
    if report[0x50:0x90] != hashlib.sha512(nonce).digest():
        problems.append("REPORT_DATA does not bind our nonce (replay?)")
    if report[0x90:0xC0] != EXPECTED:
        problems.append("MEASUREMENT is not the image we built")
    if policy >> 19 & 1:
        problems.append("POLICY.DEBUG=1: host may read guest memory")
    problems += [f"TCB {k}={got[k]} below {v}" for k, v in MIN_TCB.items() if got[k] < v]
    if not platform >> 5 & 1:
        problems.append("ALIAS_CHECK_COMPLETE=0: no BadRAM mitigation proof")
    return problems or ["all checks passed: release the secret"]

nonce = b"verifier-nonce-7f3a"
good = make_report(nonce, EXPECTED)
bad = make_report(b"old-nonce", EXPECTED, debug=True,
                  tcb_v=tcb(3, 0, 7, 115), alias_checked=False)
for name, rep in (("good", good), ("bad", bad)):
    print(name, len(rep), "bytes")
    for p in verify(rep, nonce): print("  ", p)
